import json
import sys
import time
from pathlib import Path

sys.path.insert(0, str(Path(__file__).parent / 'mdict-analysis'))
sys.path.insert(0, str(Path(__file__).parent / 'pydeps'))
from readmdict import MDX, MDD


class Bench:
    @staticmethod
    def memory():
        values = {}
        for line in Path('/proc/self/status').read_text().splitlines():
            fields = line.split()
            if fields and fields[0] in ('VmRSS:', 'VmHWM:'):
                values[fields[0][:-1]] = int(fields[1])
        return values

    @classmethod
    def run(cls, mode, path):
        before = cls.memory()
        start = time.perf_counter_ns()
        reader = MDD(path) if mode == 'resources' else MDX(path)
        open_ms = (time.perf_counter_ns() - start) / 1e6
        after_open = cls.memory()
        start = time.perf_counter_ns()
        first = next(reader.items())
        first_ms = (time.perf_counter_ns() - start) / 1e6
        result = {'engine': 'python', 'mode': mode, 'path': path, 'count': len(reader), 'open_ms': open_ms, 'first_ms': first_ms, 'before_kib': before, 'open_kib': after_open}
        if mode in ('scan', 'probe', 'resources'):
            start = time.perf_counter_ns()
            count = total = 0
            records = []
            for key, value in reader.items():
                count += 1
                total += len(value)
                if mode == 'probe':
                    records.append({'key': key.decode('utf-8'), 'text': value.decode('utf-8')})
                elif mode == 'resources':
                    records.append({'key': key.decode('utf-8'), 'bytes': len(value), 'sum': sum(value)})
            result.update(scan_ms=(time.perf_counter_ns() - start) / 1e6, scanned=count, bytes=total)
            if mode == 'probe':
                result['records'] = records
            elif mode == 'resources':
                result['resources'] = records
        result['end_kib'] = cls.memory()
        return result


if __name__ == '__main__':
    try:
        print(json.dumps(Bench.run(sys.argv[1], sys.argv[2]), ensure_ascii=False))
    except Exception as error:
        print(json.dumps({'engine': 'python', 'path': sys.argv[2], 'error': str(error), 'kind': type(error).__name__}, ensure_ascii=False))
        raise SystemExit(1)

