import json
import subprocess
from pathlib import Path


class Measure:
    root = Path(__file__).parent
    binary = root / 'harness/target/release/mdict-comparison'

    @classmethod
    def run(cls, engine, mode, size, trial):
        path = cls.root / 'corpus' / f'bench-{size}.mdx'
        command = ['python', str(cls.root / 'python-bench.py'), mode, str(path)] if engine == 'python' else [str(cls.binary), engine, mode, str(path)]
        command = ['prlimit', '--as=1073741824', '--', 'taskset', '-c', '2', *command]
        process = subprocess.run(command, text=True, capture_output=True, timeout=180)
        data = json.loads(process.stdout.strip().splitlines()[-1])
        data.update(engine=engine, mode=mode, size=size, trial=trial, exit=process.returncode)
        if process.returncode:
            raise RuntimeError(data)
        if mode == 'scan' and (data['scanned'] != size or data['bytes'] != size * 511):
            raise RuntimeError(f'Unequal decoded work: {data}')
        if mode == 'lookup':
            for pattern in ('repeat', 'random'):
                if data[pattern]['bytes'] != 511000:
                    raise RuntimeError(f'Unequal lookup work: {data}')
        return data

    @classmethod
    def main(cls):
        output = cls.root / 'measurements.jsonl'
        with output.open('w') as stream:
            for size in (10000, 100000):
                (cls.root / 'corpus' / f'bench-{size}.mdx').read_bytes()
                for mode, trials, engines in (
                    ('open', 9, ['woyo-reader', 'woyo-index', 'lazy', 'stream', 'python']),
                    ('lookup', 5, ['woyo-index', 'lazy']),
                    ('scan', 3, ['woyo-reader', 'lazy', 'stream', 'python']),
                ):
                    for trial in range(trials):
                        shift = trial % len(engines)
                        for engine in engines[shift:] + engines[:shift]:
                            data = cls.run(engine, mode, size, trial)
                            stream.write(json.dumps(data) + '\n')
                            stream.flush()
                        print(json.dumps({'size':size,'mode':mode,'trial':trial,'complete':True}), flush=True)
        print(json.dumps({'output':str(output),'complete':True}), flush=True)


if __name__ == '__main__':
    Measure.main()
